use super::*;
use atlas_faiss_probe::overlay::{DeltaSnapshot,FlatOverlay};
use std::collections::{BTreeMap,HashMap,HashSet};

type Groups=BTreeMap<String,Vec<Value>>;
fn group(rows:&[Value])->Result<Groups,String>{let mut out=Groups::new();for row in rows{let id=row["id"].as_str().ok_or("invalid source id")?;out.entry(id.to_owned()).or_default().push(row.clone());}Ok(out)}
fn rows(data:&Value)->Result<&Vec<Value>,String>{data["records"].as_array().ok_or_else(||"invalid metadata".into())}
fn hash(data:&[u8])->String{format!("{:x}",Sha256::digest(data))}
fn parse(base:Index,base_meta:&Value,delta:&[u8],manifest:&Value)->Result<(FlatOverlay,Vec<Value>),String>{
 if manifest["key"]!=base_meta["key"]||manifest["base_index_sha256"]!=base_meta["index_sha256"]||manifest["delta_sha256"]!=hash(delta){return Err("index identity mismatch".into())}
 let base_rows=rows(base_meta)?;let keys=base_rows.iter().map(|x|x["id"].as_str().map(str::to_owned).ok_or("invalid source id")).collect::<Result<Vec<_>,_>>()?;
 let snapshot=DeltaSnapshot{index:delta.to_vec(),changed_keys:serde_json::from_value(manifest["changed_keys"].clone()).map_err(|e|e.to_string())?,records:serde_json::from_value(manifest["delta_records"].clone()).map_err(|e|e.to_string())?,removed:serde_json::from_value(manifest["removed"].clone()).map_err(|e|e.to_string())?,hidden:serde_json::from_value(manifest["hidden"].clone()).map_err(|e|e.to_string())?};
 let delta_rows=manifest["delta_metadata"].as_array().ok_or("invalid delta metadata")?.clone();if snapshot.records.len()!=delta_rows.len(){return Err("delta metadata mismatch".into())}for ((id,_),row) in snapshot.records.iter().zip(&delta_rows){if row["id"].as_str()!=Some(id){return Err("delta metadata id mismatch".into())}}
 Ok((FlatOverlay::from_snapshot(base,keys,snapshot)?,delta_rows))
}
fn metadata(doc:&Source<'_>)->Result<Vec<Value>,String>{let mut out=Vec::new();for(field,text)in [("body",doc.body),("description",doc.description)]{if text.trim().is_empty(){continue}for c in split(text)?{let fragment=c["text"].as_str().ok_or("missing text")?;out.push(json!({"id":doc.id,"title":doc.title,"field":field,"input_hash":input_hash(&format!("{}\n{fragment}",doc.title)),"text":fragment,"start":c["start"],"end":c["end"],"start_utf16":c["start_utf16"],"end_utf16":c["end_utf16"]}));}}if doc.body.trim().is_empty()&&!doc.title.trim().is_empty(){out.push(json!({"id":doc.id,"title":doc.title,"field":"title","input_hash":input_hash(doc.title),"text":doc.title,"start":null,"end":null}));}Ok(out)}
/// Build only changed vectors while reading source objects sequentially.
pub fn prepare(model:&Encoder,base:Index,base_meta:&Value,previous:Option<(&[u8],&Value)>,mut next:impl FnMut()->Result<Option<(String,String,String,String)>,String>,mut image:impl FnMut(&str)->Result<Option<Vec<u8>>,String>,trash:&[String],should_continue:impl Fn()->bool,progress:impl Fn(&str,usize,usize))->Result<(Vec<u8>,Value,Option<(Vec<u8>,Value)>),String>{
 if base_meta["key"]!=model.identity(){return Err("model key mismatch".into())}
 let base_rows=rows(base_meta)?;if base.count()!=base_rows.len() as i64{return Err("base count mismatch".into())}let base_count=base.count() as usize;
 let mut cache=HashMap::<String,(bool,i64)>::new();let mut new_vectors=HashMap::<String,Box<[f32;512]>>::new();for(i,row)in base_rows.iter().enumerate(){if let Some(h)=row["input_hash"].as_str(){cache.insert(h.to_owned(),(false,i as i64));}}
 let (mut overlay,old_delta)=if let Some((delta,m))=previous{let di=Index::from_memory(delta).map_err(str::to_string)?;let ds=m["delta_metadata"].as_array().ok_or("invalid delta metadata")?;if di.count()!=ds.len() as i64{return Err("delta count mismatch".into())}for(i,row)in ds.iter().enumerate(){if let Some(h)=row["input_hash"].as_str(){cache.insert(h.to_owned(),(true,i as i64));}}parse(base,base_meta,delta,m)?}else{let ids=base_rows.iter().map(|x|x["id"].as_str().map(str::to_owned).ok_or("invalid source id")).collect::<Result<Vec<_>,_>>()?;(FlatOverlay::new(base,ids)?,Vec::new())};
 let mut current=group(base_rows)?;let mut delta_groups=group(&old_delta)?;if let Some((_,m))=previous{for key in m["changed_keys"].as_array().ok_or("invalid changed keys")?.iter().chain(m["removed"].as_array().ok_or("invalid removed keys")?){current.remove(key.as_str().ok_or("invalid key")?);}for(id,values)in &delta_groups{current.insert(id.clone(),values.clone());}}
 let mut seen=HashSet::new();let trash=trash.iter().map(String::as_str).collect::<HashSet<_>>();let mut updates=Vec::new();let mut encoded_count=0usize;let mut visible_count=0usize;let mut visible_metadata=0usize;let(vector_limit,metadata_limit)=super::memory_limits();
 while let Some((id,title,body,description))=next()?{if !should_continue(){return Err("indexing cancelled".into())}if !seen.insert(id.clone()){return Err("duplicate source".into())}let doc=Source{id:&id,title:&title,body:&body,description:&description};let mut target=metadata(&doc)?;
  let mime=match Path::new(&title).extension().and_then(|s|s.to_str()).unwrap_or("").to_ascii_lowercase().as_str(){"png"=>Some("image/png"),"jpg"|"jpeg"=>Some("image/jpeg"),"webp"=>Some("image/webp"),"gif"=>Some("image/gif"),_=>None};if model.supports_images(){if let Some(mime)=mime{match image(&id){Ok(Some(bytes))=>{let h=format!("image:{}",hash(&bytes));let available=if cache.contains_key(&h)||new_vectors.contains_key(&h){true}else{match model.encode_image(&bytes,mime).and_then(|v|v.try_into().map_err(|_|"invalid dimensions".to_owned())){Ok(v)=>{new_vectors.insert(h.clone(),Box::new(v));encoded_count+=1;true},Err(e)=>{eprintln!("Atlas: image indexing skipped: {e}");false}}};if available{target.push(json!({"id":id,"title":title,"field":"image","input_hash":h,"text":"","start":null,"end":null}));}},Ok(None)=>{},Err(e)=>eprintln!("Atlas: image indexing skipped: {e}")}}}
  visible_count=visible_count.saturating_add(target.len());if visible_count>vector_limit{return Err("Смысловой поиск ограничен 16 000 фрагментов".into())}for row in &target{visible_metadata=visible_metadata.saturating_add(serde_json::to_vec(row).map_err(|_|"invalid record")?.len()).saturating_add(80);if visible_metadata>metadata_limit{return Err("Метаданные смыслового поиска превышают 32 МиБ".into())}}
  if current.get(&id)==Some(&target){overlay.revive(&id)?;continue}
  let mut vectors=Vec::with_capacity(target.len());for(i,row)in target.iter().enumerate(){if !should_continue(){return Err("indexing cancelled".into())}let h=row["input_hash"].as_str().ok_or("missing hash")?;let vector=if let Some(&(is_delta,at))=cache.get(h){if is_delta{overlay.reconstruct_delta(at)?}else{overlay.reconstruct_base(at)?}}else if let Some(v)=new_vectors.get(h){**v}else{let input=if row["field"]=="title"{title.clone()}else{format!("{}\n{}",title,row["text"].as_str().ok_or("missing text")?)};let v:Vec<f32>=model.encode(&input,false)?;let v:[f32;512]=v.try_into().map_err(|_|"invalid dimensions")?;new_vectors.insert(h.to_owned(),Box::new(v));encoded_count+=1;v};vectors.push(vector);progress(&title,i+1,target.len());}delta_groups.insert(id.clone(),target);updates.push((id,Some(vectors)));
 }
 let mut purged=false;for id in current.keys(){if seen.contains(id){continue}if trash.contains(id.as_str()){overlay.hide(id)?;if let Some(rows)=current.get(id){visible_count=visible_count.saturating_add(rows.len());for row in rows{visible_metadata=visible_metadata.saturating_add(serde_json::to_vec(row).map_err(|_|"invalid record")?.len()).saturating_add(80);}}}else{overlay.purge(id)?;delta_groups.remove(id);purged=true;}}
 if visible_count>vector_limit{return Err("Смысловой поиск ограничен 16 000 фрагментов".into())}if visible_metadata>metadata_limit{return Err("Метаданные смыслового поиска превышают 32 МиБ".into())}overlay.apply_batch(updates)?;
 let mut snapshot=overlay.snapshot_delta()?;let mut delta_rows=Vec::with_capacity(snapshot.records.len());for(id,pos)in &snapshot.records{delta_rows.push(delta_groups.get(id).and_then(|v|v.get(*pos)).ok_or("missing delta row")?.clone());}
 let compact=purged||base_count.saturating_mul(2048).saturating_add(snapshot.index.len())>32*1024*1024;
 let mut new_base=None;let mut base_sha=base_meta["index_sha256"].clone();if compact{
  let hidden=overlay.hidden_keys();let changed=snapshot.changed_keys.iter().map(String::as_str).collect::<HashSet<_>>();let(index,mapping)=overlay.materialize_cancellable(true,&should_continue)?;let mut records=Vec::with_capacity(mapping.len());for(id,pos)in &mapping{let source=if changed.contains(id.as_str()){delta_groups.get(id)}else{current.get(id)};records.push(source.and_then(|v|v.get(*pos)).ok_or("missing compacted row")?.clone());}let bytes=index.to_memory().map_err(str::to_string)?;base_sha=json!(hash(&bytes));let mut meta=base_meta.clone();meta["records"]=json!(records);meta["index_sha256"]=base_sha.clone();meta["encoded_count"]=json!(encoded_count);let keys=mapping.into_iter().map(|(id,_)|id).collect();let mut refreshed=FlatOverlay::new(index,keys)?;for id in hidden{refreshed.hide(&id)?;}snapshot=refreshed.snapshot_delta()?;delta_rows.clear();new_base=Some((bytes,meta));
 }
 let manifest=json!({"key":model.identity(),"base_index_sha256":base_sha,"delta_sha256":hash(&snapshot.index),"changed_keys":snapshot.changed_keys,"delta_records":snapshot.records,"removed":snapshot.removed,"hidden":snapshot.hidden,"delta_metadata":delta_rows,"encoded_count":encoded_count});Ok((snapshot.index,manifest,new_base))
}
pub enum SearchIndex { Legacy(Index,Value), Partial(FlatOverlay,Groups,Groups,HashSet<String>,String) }
pub fn load_search(base:Index,base_meta:Value,previous:Option<(&[u8],&Value)>)->Result<SearchIndex,String>{
 let Some((bytes,m))=previous else{return Ok(SearchIndex::Legacy(base,base_meta))};
 let base_groups=group(rows(&base_meta)?)?;let key=base_meta["key"].as_str().ok_or("missing model identity")?.to_owned();let changed=m["changed_keys"].as_array().ok_or("invalid changed keys")?.iter().map(|v|v.as_str().map(str::to_owned).ok_or("invalid key".to_owned())).collect::<Result<HashSet<_>,_>>()?;let(overlay,delta_rows)=parse(base,&base_meta,bytes,m)?;let delta_groups=group(&delta_rows)?;Ok(SearchIndex::Partial(overlay,base_groups,delta_groups,changed,key))
}
pub fn search(model:&Encoder,index:&SearchIndex,q:&str,filter:Option<&[String]>,k:usize)->Result<Vec<Value>,String>{match index{
 SearchIndex::Legacy(i,m)=>super::search_memory(model,i,m,q,filter,k),
 SearchIndex::Partial(overlay,base,delta,changed,key)=>{if key!=model.identity(){return Err("model key mismatch".into())}let vector:[f32;512]=model.encode(q,true)?.try_into().map_err(|_|"invalid dimensions")?;overlay.search(&vector,filter,k)?.into_iter().map(|(id,pos,score)|{let mut row=if changed.contains(&id){delta.get(&id)}else{base.get(&id)}.and_then(|rows|rows.get(pos)).ok_or("missing result metadata")?.clone();row["score"]=json!(score);Ok(row)}).collect()}
}}
#[cfg(test)]mod tests{
 use super::*;
 #[test]#[ignore="requires local real model"]fn real_edit_hide_revive(){
  let model=Encoder::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-pair-eval/model-q8.gguf").unwrap();
  let mut b=MemoryBuilder::new(&model,None).unwrap();for(id,title,body)in[("a","Огород","Поливайте помидоры"),("b","Дорога","Вокзал и билеты")]{b.push(&model,&Source{id,title,body,description:""},&||true).unwrap()};let(bytes,base_meta)=b.finish(&model).unwrap();
  let source=|items:Vec<(&str,&str,&str)>|items.into_iter().map(|(i,t,b)|(i.to_owned(),t.to_owned(),b.to_owned(),String::new())).collect::<Vec<_>>();
  let mut docs=source(vec![("a","Огород","Поливайте томаты вечером"),("b","Дорога","Вокзал и билеты")]).into_iter();let(d1,m1,_)=prepare(&model,Index::from_memory(&bytes).unwrap(),&base_meta,None,||Ok(docs.next()),|_|Ok(None),&[],||true,|_,_,_|{}).unwrap();assert_eq!(m1["encoded_count"],1);let idx=load_search(Index::from_memory(&bytes).unwrap(),base_meta.clone(),Some((&d1,&m1))).unwrap();let found=search(&model,&idx,"Как поливать томаты?",Some(&["a".into()]),5).unwrap();assert_eq!(found.len(),1);assert_eq!(found[0]["text"],"Поливайте томаты вечером");
  let mut docs=source(vec![("b","Дорога","Вокзал и билеты")]).into_iter();let(d2,m2,_)=prepare(&model,Index::from_memory(&bytes).unwrap(),&base_meta,Some((&d1,&m1)),||Ok(docs.next()),|_|Ok(None),&["a".into()],||true,|_,_,_|{}).unwrap();let idx=load_search(Index::from_memory(&bytes).unwrap(),base_meta.clone(),Some((&d2,&m2))).unwrap();assert!(search(&model,&idx,"томаты",Some(&["a".into()]),5).unwrap().is_empty());
  let mut docs=source(vec![("a","Огород","Поливайте томаты вечером"),("b","Дорога","Вокзал и билеты")]).into_iter();let(d3,m3,_)=prepare(&model,Index::from_memory(&bytes).unwrap(),&base_meta,Some((&d2,&m2)),||Ok(docs.next()),|_|Ok(None),&[],||true,|_,_,_|{}).unwrap();assert_eq!(m3["encoded_count"],0);let idx=load_search(Index::from_memory(&bytes).unwrap(),base_meta,Some((&d3,&m3))).unwrap();assert_eq!(search(&model,&idx,"томаты",Some(&["a".into()]),5).unwrap().len(),1);
 }
}
/// A new model needs fresh vectors even for objects in the one-day trash.
pub fn full_with_hidden(bytes:Vec<u8>,meta:Value,trash:&[String])->Result<(Vec<u8>,Value,Option<(Vec<u8>,Value)>),String>{
 let index=Index::from_memory(&bytes).map_err(str::to_string)?;let base_rows=rows(&meta)?;let ids=base_rows.iter().map(|r|r["id"].as_str().map(str::to_owned).ok_or("invalid source id")).collect::<Result<Vec<_>,_>>()?;let mut overlay=FlatOverlay::new(index,ids)?;for id in trash{if overlay.has_key(id){overlay.hide(id)?;}}let snap=overlay.snapshot_delta()?;let manifest=json!({"key":meta["key"],"base_index_sha256":meta["index_sha256"],"delta_sha256":hash(&snap.index),"changed_keys":snap.changed_keys,"delta_records":snap.records,"removed":snap.removed,"hidden":snap.hidden,"delta_metadata":[],"encoded_count":meta["encoded_count"]});Ok((snap.index,manifest,Some((bytes,meta))))
}
